// Объявление массива через квадратные скобки
const fruits = ["яблоко", "банан", "вишня"];

// Индексация с НУЛЯ:
console.log(fruits[0]);   // яблоко — первый элемент
console.log(fruits[1]);   // банан — второй элемент
console.log(fruits[2]);   // вишня — третий элемент
console.log(fruits[3]);   // undefined — четвёртого элемента нет!

// Длина массива — свойство length (без скобок!)
console.log(fruits.length);  // 3
// Последний индекс = length - 1 = 2

const arr = [1, 2, 3];

// Массив — это объект:
console.log(typeof arr);        // "object" — не "array"!
console.log(Array.isArray(arr)); // true — правильная проверка

// У массива есть свойства и методы:
console.log(arr.length);        // 3
console.log(arr.push(4));       // 4 — добавили элемент

// Можно даже добавить своё свойство (но не стоит):
arr.custom = "hello";
console.log(arr.custom);        // hello
console.log(arr.length);        // 4 — custom НЕ считается элементом

const tasks = ["задача1", "задача2"];

// push — добавить в конец:
tasks.push("задача3");
console.log(tasks);   // ["задача1", "задача2", "задача3"]

// pop — убрать с конца:
const last = tasks.pop();  // вернул "задача3"
console.log(tasks);   // ["задача1", "задача2"] — изменился!
console.log(last);    // задача3

const queue = ["второй", "третий"];

// unshift — в начало:
queue.unshift("первый");
console.log(queue);   // ["первый", "второй", "третий"]

// shift — из начала:
const first = queue.shift();  // вернул "первый"
console.log(queue);   // ["второй", "третий"]
console.log(first);   // первый

const arr = [10, 20, 30, 40, 50];

// slice — копия, оригинал НЕ меняется:
const part = arr.slice(1, 3);   // берём индексы 1 и 2
console.log(part);              // [20, 30]
console.log(arr);               // [10, 20, 30, 40, 50] — цел!

// splice — МУТАЦИЯ: удаляет/вставляет на месте
const removed = arr.splice(1, 2);  // с индекса 1 удалить 2 элемента
console.log(removed);           // [20, 30] — удалённые
console.log(arr);               // [10, 40, 50] — оригинал ИЗМЕНЁН

