const colors = ["red", "green", "blue"];

// indexOf — позиция элемента:
console.log(colors.indexOf("green"));  // 1
console.log(colors.indexOf("pink"));   // -1 — не найдено

// includes — есть ли элемент:
console.log(colors.includes("red"));   // true
console.log(colors.includes("pink"));  // false

// Классический паттерн: проверить и получить индекс
const idx = colors.indexOf("blue");
if (idx !== -1) {
  console.log("Найден на позиции:", idx);  // 2
}

const scores = [10, 20, 30];

// Классический for — с индексом:
for (let i = 0; i < scores.length; i++) {
  console.log(scores[i]);  // 10, 20, 30
}

// for...of — только значения (без индексов):
for (const score of scores) {
  console.log(score);  // 10, 20, 30
}

// Сумма элементов массива:
let sum = 0;
for (const score of scores) {
  sum += score;
}
console.log(sum);  // 60

